def lookup(date, states):
    """None means outside coverage; empty lists mean recorded no meetings."""
    if not START <= date <= END:
        return None
    if any(state not in STATES for state in states):
        raise ValueError('Historical snapshot covers QLD, NSW, VIC, SA and WA only.')
    extra = _EXTRA_MONTHS.get(date.strftime('%Y-%m'))
    if extra is not None:
        return {state: list(extra['days'][str(date.day)].get(state, [])) for state in states}
    if date.year == 2026 and date.month == 9:
        return {state: list(_DAYS[date.day].get(state, [])) for state in states}
    return None

def details(date, states):
    extra = _EXTRA_MONTHS.get(date.strftime('%Y-%m'), {})
    selected = lambda rows: [r for r in rows if r['date'] == date.isoformat() and r['state'] in states]
    return {'recorded_on': '2026-10-20' if extra else '2026-10-19',
            'excluded_abandoned': selected(extra.get('excluded_abandoned', [])),
            'calendar_status_unconfirmed': selected(extra.get('unconfirmed', []))}

